//! Generated by `everything-rust app wire` from everything-rust.json; it is rewritten on every wire.

use std::process::ExitCode;

use clap::ArgMatches;

mod js_format;

/// `EVERYTHING_RUST_UNIT_<NAME>=original` sends that unit back to the original.
fn sent_to_original(unit: &str) -> bool {
    std::env::var(format!("EVERYTHING_RUST_UNIT_{unit}")).is_ok_and(|v| v == "original")
}

pub fn dispatch(command: &str, matches: &ArgMatches) -> Option<ExitCode> {
    match command {
        "prettier" if !sent_to_original("JS_FORMAT") => Some(js_format::run(command, matches)),
        _ => None,
    }
}
